const fs = require('fs');
const path = require('path');

const data = {
  "16": "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAbklEQVR4nGOw2PvjPyWYAZugwM5GFEyUAfziWhga0TFIDQxjGEBIM7oheA34Yh8HxkQbgE0zCMMUYzOEJAPQDcFrAHpgUcUAgl7AZwhZsUBWNBKTkPB6gZCf0cXxGoAPoxuCNTMRwsiGkGUAsiEA8PVZ4xg1BQsAAAAASUVORK5CYII=",
  "48": "",
  "128": ""
};

const iconsDir = path.join(__dirname, '..', 'dupescout', 'extension', 'icons');
if (!fs.existsSync(iconsDir)) {
  fs.mkdirSync(iconsDir, { recursive: true });
}

for (const [size, b64] of Object.entries(data)) {
  const buf = Buffer.from(b64, 'base64');
  const filePath = path.join(iconsDir, `icon-${size}.png`);
  fs.writeFileSync(filePath, buf);
  console.log(`Saved ${filePath} (${buf.length} bytes)`);
}
